"""Streaming DMD with an isolated, fixed student conditioning prefix.

The bootstrap keeps dense attention. From the first continuation onwards,
the student's Qwen rows, picture, sink AV and aligned sink references form
P. P attends only P, while the recent/current rows attend the whole window.
The generated sink and its near-clean corruption stay fixed across the
chain. Every training forward recomputes P with current model parameters,
including its gradient path during GEN. No graph or DiT KV survives a
training forward. Both ODE and renoising DMD retain their usual rollout,
FAKE, GEN and optimizer ordering.

Inference prefills P on the first continuation separately for each paired
diffusion timestep and guidance branch, then reuses that bank for the rest
of the stream. Text keeps the current video timestep, so different denoising
stages never share KV. Fake and real scores retain their original dense
windows and independently perturbed conditioning.

Select this meta and the parameter-compatible causal student wrapper::

    meta_model:
      module: dev.yanzuolu.projects.minimax_h3_videoref.meta_models.minimax_h3_video_ref_streaming_prefix_dmd
      class_name: MiniMaxH3VideoRefStreamingPrefixDMD
      fixed_window_rope: true
      separate_reference_rope: true
      qwen_reference_video: false
    models:
      backbone:
        module: dev.yanzuolu.projects.minimax_h3.modeling.build
        class_name: MiniMaxH3CausalX0DiTSP
        placement:
          fsdp:
            wrap_modules: [CausalMiniMaxH3DiTBlock]

The EMA inherits the student wrapper. Keep fake_model and tea_model on their
existing wrappers. MiniMaxH3CausalX0DiT also works without sequence
parallelism. The forward helper checks the actual model type, so a dense
student cannot silently ignore the prefix mask.

This variant requires a static sink fully generated by the bootstrap,
fixed captions and Qwen context, and does not combine with history_refresh.
Its fixed corruption seed derives from the already checkpointed chain head
seed and is broadcast with the window payload, including for UP sources
whose chain pool lives on another rank.
"""

from __future__ import annotations

from dataclasses import dataclass, replace
from typing import Any

import torch

from dev.yanzuolu.common.seed import RandomState, combine_seed
from dev.yanzuolu.projects.minimax_h3.modeling.streaming import StreamingInputs
from dev.yanzuolu.projects.minimax_h3.modeling.streaming_prefix import streaming_prefix_media_masks
from dev.yanzuolu.projects.minimax_h3.modeling.transformer.x0_model import MINIMAX_H3_VIDEO_CLEAN_TIMESTEP
from dev.yanzuolu.projects.minimax_h3_videoref.meta_models.minimax_h3_video_ref_streaming_dmd import (
    MiniMaxH3VideoRefStreamingDMD,
    VideoRefStreamingDMDInputs,
)
from dev.yanzuolu.projects.minimax_h3_videoref.meta_models.minimax_h3_video_ref_streaming_rf import _ChainState
from dev.yanzuolu.projects.minimax_h3_videoref.modeling.streaming_prefix_inference import (
    VideoRefStreamingPrefixInferenceMixin,
    validate_static_prefix_captions,
)


@dataclass(frozen=True)
class _PrefixStreamingInputs(StreamingInputs):
    """Student inputs whose forwards isolate the conditioning prefix."""


class FixedStudentPrefixDMDMixin(VideoRefStreamingPrefixInferenceMixin):
    """Fix student prefix inputs for a DMD host and cache its KV during inference."""

    def __init__(self, config: Any) -> None:
        if config.meta_model.get("history_refresh", False):
            raise ValueError("a fixed student prefix cannot combine with history_refresh")
        super().__init__(config)
        if not self.fixed_window_rope:
            raise ValueError("a fixed student prefix requires fixed_window_rope")
        if self.qwen_visual_context and self.qwen_reference_video:
            raise ValueError("a fixed student prefix requires qwen_reference_video false")
        self._validate_prefix_policy(self.streaming_config)

    def _validate_prefix_policy(self, policy: dict[str, Any]) -> None:
        """Require one complete sink with unchanged positions throughout a stream."""
        sink = int(policy["sink_size"])
        if policy.get("sink_size_after_switch") not in (None, sink):
            raise ValueError("a fixed student prefix requires a constant sink_size")
        bootstrap = policy.get("bootstrap_size")
        if bootstrap is None:
            bootstrap = int(policy["window_size"]) + int(policy["chunk_size"])
        if sink > int(bootstrap):
            raise ValueError("the bootstrap must generate the complete fixed student sink")

    def _chain_head_inputs(self, batch: dict[str, Any]):
        validate_static_prefix_captions(batch.get("caption_segments"))
        for policy in batch["streaming_config"]:
            self._validate_prefix_policy(self._streaming_policy(policy))
        return super()._chain_head_inputs(batch)

    def prepare_inputs(self, ctx: dict[str, Any]) -> dict[str, Any]:
        """Normalize empty caption metadata before the host builds its own input payload."""
        batch = ctx["batch"]
        if "caption_segments" in batch and not any(batch["caption_segments"] or ()):
            ctx = dict(ctx, batch={key: value for key, value in batch.items() if key != "caption_segments"})
        return super().prepare_inputs(ctx)

    def _chain_window_payload(self, entry: _ChainState, window: int) -> dict[str, Any]:
        return dict(
            super()._chain_window_payload(entry, window),
            student_prefix_seed=combine_seed(entry.seed, "student_prefix", entry.chain_id, entry.offset + 1),
        )

    def _finish_dmd_window(
        self, inputs: VideoRefStreamingDMDInputs, *, view: dict[str, Any], plans: list[dict[str, Any]],
        rngs: list[RandomState], rng: RandomState,
    ) -> VideoRefStreamingDMDInputs:
        """Freeze only student P rows while leaving score inputs and W/C unchanged."""
        inputs = super()._finish_dmd_window(inputs, view=view, plans=plans, rngs=rngs, rng=rng)
        anchor = MINIMAX_H3_VIDEO_CLEAN_TIMESTEP
        prefix_rng = RandomState(int(view["encoded_batch"]["student_prefix_seed"]))
        sample_rngs = [prefix_rng.fork("sample", index) for index in range(inputs.batch_size)]
        history = (list(inputs.history[0]), list(inputs.history[1]))
        for index, (plan, sample_rng) in enumerate(zip(inputs.plans, sample_rngs, strict=True)):
            rows = streaming_prefix_media_masks(plan)["video"].nonzero().flatten()
            if not rows.numel():
                continue
            indices = plan["video_indices"].index_select(0, rows)
            raw = self._select(view["clean_latents"][0][index], indices).detach().float()
            conditioned = anchor * raw + (1 - anchor) * self._noise(raw, sample_rng.fork("video"))
            history[0][index] = history[0][index].index_copy(1, rows.to(conditioned.device), conditioned)

        def student_window(window: StreamingInputs | None) -> StreamingInputs | None:
            if window is None:
                return None
            frozen_plans = list(window.plans)
            references = None if window.reference_latents is None else list(window.reference_latents)
            for index, (plan, sample_rng) in enumerate(zip(window.plans, sample_rngs, strict=True)):
                if plan["is_bootstrap"]:
                    continue
                if plan.get("picture_shape") is not None:
                    raw = plan["picture_clean_latents"].to(plan["picture_latents"])
                    picture = anchor * raw + (1 - anchor) * self._noise(raw, sample_rng.fork("picture"))
                    frozen_plans[index] = dict(plan, picture_latents=picture)
                if references is not None:
                    rows = streaming_prefix_media_masks(plan)["reference"].nonzero().flatten()
                    indices = plan["reference_video_indices"].index_select(0, rows)
                    raw = self._select(view["inputs"].reference_latents[index], indices).detach().float()
                    conditioned = anchor * raw + (1 - anchor) * self._noise(raw, sample_rng.fork("reference"))
                    references[index] = references[index].index_copy(1, rows.to(conditioned.device), conditioned)
            return _PrefixStreamingInputs(**dict(vars(window), plans=frozen_plans, reference_latents=references))

        return replace(
            inputs, history=history, window_inputs=student_window(inputs.window_inputs),
            negative_window_inputs=student_window(inputs.negative_window_inputs),
            branch_windows=(None if inputs.branch_windows is None else
                            {name: student_window(value) for name, value in inputs.branch_windows.items()}),
            score_window=inputs if inputs.score_window is None else inputs.score_window,
        )

    def _streaming_forward(
        self, model: Any, inputs: StreamingInputs, **kwargs: Any,
    ) -> tuple[list[torch.Tensor], list[torch.Tensor]]:
        if isinstance(inputs, _PrefixStreamingInputs):
            return self._streaming_prefix_forward(model, inputs, **kwargs)
        return super()._streaming_forward(model, inputs, **kwargs)


class MiniMaxH3VideoRefStreamingPrefixDMD(FixedStudentPrefixDMDMixin, MiniMaxH3VideoRefStreamingDMD):
    """Train chain windows with a fresh masked student prefix and cache its KV during inference."""
